    })
    db.node.addDependency(vpc)

    var db = new rds.CfnDBInstance(this, "private-public-subnet", {
      engine: "postgres",
      masterUsername: "foobar",
      masterUserPassword: "12345678",
      dbInstanceClass: "db.r5.large",
